        block_counts[block] = block_counts.get(block, 0) + 1

print(f"Unique 2x2 blocks: {len(block_counts)}")
for b, count in sorted(block_counts.items(), key=lambda x: -x[1])[:5]:
    print(f"  {b}: {count}")

# Let me also try looking at row repetition patterns
print("\n\nRow analysis - checking for repeated rows:")
unique_rows = {}
for i, row in enumerate(grid):
    row_tuple = tuple(row)
    if row_tuple not in unique_rows:
        unique_rows[row_tuple] = []
    unique_rows[row_tuple].append(i)

for row_tuple, indices in unique_rows.items():
    if len(indices) >= 2:
        print(f"  Row pattern appears {len(indices)} times at rows: {indices}")

# Try another potential answer - maybe count 5s in each row/col as output?
# Or maybe transform based on component connectivity

# Let me check if there's any pattern where 6s surround 5s or vice versa
# Look at local neighborhood patterns

def get_nhood_pattern(grid, i, j, radius=1):
    """Get pattern around position (i,j) with given radius"""
    height, width = grid.shape
    h = min(radius, height - max(i, 0) - 1 if radius else 0)

    # Create mask
    result = []
    for di in range(-radius*2, radius+1):
        row_patterns = []
        for dj in range(-radius*2, radius+1):
            ni, nj = i + di, j + dj
            if 0 <= ni < height and 0 <= nj < width:
                row_patterns.append(grid[ni][nj])
            else:
                row_patterns.append(0)  # Padding
        result.append(tuple(row_patterns))
    return tuple(result)

# Check unique nhood patterns
nhood_counts = {}
for i in range(height):
    for j in range(width):
        pattern = get_nhood_pattern(grid, i, j)
        nhood_counts[pattern] = nhood_counts.get(pattern, 0) + 1

print(f"Number of unique 3x3 neighborhoods: {len(nhood_counts)}")
top_patterns = sorted(nhood_counts.items(), key=lambda x: -x[1])[:5]
for pattern, count in top_patterns:
    print(f"  Pattern (count={count}): {pattern}")

